commit 76592d4fa7b829e67fa7ee0532296b40850ecb3e
Author: maint-bot <maint-bot@example.invalid>
Date:   Fri Aug 21 01:34:57 2026 +0530

    Validate edge product in Mat_VarGetCells and Mat_VarGetStructs

    Now that the edge product is validated up front, also relax
    Mat_VarGetStructs' rank check to allow the same maximum rank (10)
    already supported by the other fixed-rank slab readers in mat5.c and
    read_data.c.

    As reported by https://github.com/tbeu/matio/pull/318

    (cherry picked from commit d410ad4bd15efd286d3ee587b052847bf073c454)

    Co-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>

diff --git a/src/matvar_struct.c b/src/matvar_struct.c
index 8ccfbe7..73c15be 100644
--- a/src/matvar_struct.c
+++ b/src/matvar_struct.c
@@ -7,6 +7,7 @@
  */

 #include "matio_private.h"
+#include <limits.h>
 #include <stdlib.h>
 #include <string.h>
 #if defined(_MSC_VER) || defined(__MINGW32__)
@@ -391,7 +392,7 @@ Mat_VarGetStructs(const matvar_t *matvar, const int *start, const int *stride, c
     if ( matvar == NULL || start == NULL || stride == NULL || edge == NULL ) {
         return NULL;
     }
-    if ( matvar->rank > 9 ) {
+    if ( matvar->rank > 10 ) {
         return NULL;
     }
     if ( matvar->class_type != MAT_C_STRUCT && matvar->class_type != MAT_C_OBJECT ) {
@@ -401,6 +402,10 @@ Mat_VarGetStructs(const matvar_t *matvar, const int *start, const int *stride, c
         return NULL;
     }

+    if ( CheckEdgeOverflow(matvar->rank, edge, matvar->internal->num_fields) ) {
+        return NULL;
+    }
+
     struct_slab = Mat_VarDuplicate(matvar, 0);
     if ( NULL == struct_slab )
         return NULL;
